package com.ruoyi.medical.persistence;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import java.util.*;import java.math.*;import java.time.*;import java.sql.*;import java.util.function.Function;import org.springframework.jdbc.core.*;import com.ruoyi.medical.identity.*;import com.ruoyi.medical.contracts.*;import jakarta.servlet.http.HttpServletRequest;
/** Actual queue/service binding and delegation. Persistent token authority is separately tested by its real gate suite. */
class FormalVerificationWorkerServiceTest {
 FormalVerificationWorkerService worker;FormalInvocationSchema json;JdbcTemplate db;RunTokenAuthority tokens;ServiceCertificateIdentity identities;ServiceCertificateIdentity.Verified identity;HttpServletRequest http;FormalVerificationJobs jobs;String tenant=id(1),actor=id(2),verification=id(3),owner="spiffe://test/gateway",assigned=owner,status="RUNNING";boolean empty;FormalVerificationJobs.Job job;
 @BeforeEach void setup()throws Exception{json=new FormalInvocationSchema();db=mock(JdbcTemplate.class);tokens=mock(RunTokenAuthority.class);identities=mock(ServiceCertificateIdentity.class);identity=mock(ServiceCertificateIdentity.Verified.class);http=mock(HttpServletRequest.class);when(identities.require(http)).thenReturn(identity);when(identity.serviceUri()).thenReturn(owner);when(identity.certificateSha256()).thenReturn("a".repeat(64));when(identity.trustRevision()).thenReturn(id(99));jobs=mock(FormalVerificationJobs.class);var tx=mock(TenantTransaction.class);when(tx.execute(any())).thenAnswer(i->((Function<TenantWatermarks,Object>)i.getArgument(0)).apply(new TenantWatermarks(BigInteger.ONE,BigInteger.ONE)));var policy=mock(RunTokenPolicyStore.class,RETURNS_DEEP_STUBS);when(policy.read().policy().maximumLifetime()).thenReturn(Duration.ofSeconds(60));worker=new FormalVerificationWorkerService(mock(javax.sql.DataSource.class),identities,tx,tokens,policy,jobs,json,new RunTokenAuthoritySchema(),30);var field=worker.getClass().getDeclaredField("db");field.setAccessible(true);field.set(worker,db);
  when(jobs.read(tenant,verification)).thenAnswer(i->{String deps=json.canonical(Map.of("model",Map.of("config_id",id(16)),"principal",Map.of("services",List.of(Map.of("service_uri",assigned,"audience","gateway")),"permissions",List.of(Map.of("scope",new PermissionProtocol.Scope(tenant,id(4),"CONFIGURATION",id(16)),"action","model.send","purpose","MODEL_VERIFICATION")))));job=new FormalVerificationJobs.Job(tenant,id(4),verification,id(6),actor,"original-key-000000",id(7),id(8),id(9),id(10),id(11),id(12),id(13),id(14),id(15),"{\"request_parameters\":{\"max_output_tokens\":16}}","a".repeat(64),"b".repeat(64),deps,json.hash(json.parse(deps)),json.manifestSha256(),LocalDateTime.of(2026,10,18,0,0),"INTERNAL");return Optional.of(job);});
  when(db.query(anyString(),any(RowMapper.class),any(Object[].class))).thenAnswer(i->{String sql=i.getArgument(0);if(sql.startsWith("SELECT j.verification_id"))return empty?List.of():List.of(verification);if(sql.startsWith("SELECT created_by"))return List.of(actor);if(sql.startsWith("SELECT auth_epoch"))return List.of(new TenantWatermarks(BigInteger.ONE,BigInteger.ONE));if(sql.startsWith("SELECT s.status")){ResultSet rs=mock(ResultSet.class);when(rs.getString(1)).thenReturn(status);when(rs.getBigDecimal(2)).thenReturn(new BigDecimal("2"));when(rs.getBigDecimal(3)).thenReturn(BigDecimal.ONE);when(rs.getString(4)).thenReturn(owner);when(rs.getTimestamp(5)).thenReturn(Timestamp.valueOf("2026-10-18 00:01:00"));when(rs.getTimestamp(6)).thenReturn(Timestamp.valueOf("2026-10-18 00:00:00"));return List.of(((RowMapper<?>)i.getArgument(1)).mapRow(rs,0));}throw new AssertionError(sql);});
 }
 @Test void emptyRealQueueReturnsNoInventedJob()throws Exception{empty=true;assertFalse(worker.claim(http,tenant).required("found").booleanValue());verifyNoInteractions(tokens);}
 @Test void claimUsesStoredActorRunStepRevisionOnly()throws Exception{var lease=mock(RunTokenAuthority.Lease.class);when(lease.runId()).thenReturn(id(7));when(lease.stepId()).thenReturn(id(9));when(lease.owner()).thenReturn(owner);when(lease.generation()).thenReturn(BigInteger.TWO);when(lease.revision()).thenReturn(BigInteger.valueOf(3));when(lease.expiresAt()).thenReturn(Instant.parse("2026-10-18T00:00:30Z"));when(tokens.claimStep(eq(http),any())).thenReturn(lease);assertTrue(worker.claim(http,tenant).required("found").booleanValue());verify(tokens).claimStep(eq(http),argThat(r->r.initiatorId().equals(actor)&&r.runId().equals(id(7))&&r.stepId().equals(id(9))&&r.expectedRevision().equals(BigInteger.TWO)));}
 @Test void differentServiceAssignmentCannotMintToken(){assigned="spiffe://other/service";assertThrows(TenantAccessException.class,()->worker.issue(http,tenant,verification));verifyNoInteractions(tokens);}
 @Test void leaseMustBeOwnedByExactCurrentService(){owner="spiffe://other/lease-owner";assertThrows(TenantAccessException.class,()->worker.issue(http,tenant,verification));verifyNoInteractions(tokens);}
 @Test void issuedActionAndParametersComeFromOriginalJob()throws Exception{var issued=mock(RunTokenAuthority.Issued.class);when(issued.token()).thenReturn("fixture-issued-token");when(issued.expiresAt()).thenReturn(Instant.parse("2026-10-18T00:00:30Z"));when(tokens.issue(eq(http),any())).thenReturn(issued);var actual=worker.issue(http,tenant,verification);assertEquals(id(10),actual.required("worker_action").required("action_id").textValue());assertEquals(id(15),actual.required("model_config_revision").textValue());assertEquals(16,actual.required("request_parameters").required("max_output_tokens").intValue());verify(tokens).issue(eq(http),argThat(r->r.actions().equals(List.of("model.send"))&&r.initiatorId().equals(actor)&&r.generation().equals(BigInteger.ONE)));}
 @Test void terminalStepCannotIssueAnotherSendToken(){status="SUCCEEDED";assertThrows(TenantAccessException.class,()->worker.issue(http,tenant,verification));verifyNoInteractions(tokens);}
 static String id(int n){return "00000000-0000-4000-8000-"+String.format("%012d",n);}
}
